def reference(text: str) -> str:
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != " ":
            out.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == " ":
                j += 1
            run = j - i
            if run > 2:
                out.append("-")
            else:
                out.append("_" * run)
            i = j
    return "".join(out)

